// Original 8-bit duck PNGs supplied by the Crow HQ owner.
export const EMOJIS=Object.freeze([
 ['shock','😱','Screaming duck','scream'],['flushed','😳','Flushed duck','flushed'],
 ['angry','😡','Angry duck','rage'],['exploding','🤯','Mind blown duck','exploding'],
 ['thumbsup','👍','Thumbs up duck','thumbsup'],['sleep','😴','Sleeping duck','sleeping'],
 ['sweat','😰','Nervous duck','cold-sweat'],['laugh','😂','Laughing duck','joy'],
 ['heart','❤️','Love duck','heart'],['smoke','🚬','Smoking duck','smoke'],
].map(([id,value,label,file])=>Object.freeze({id,value,label,src:'/emoji-ducks/'+file+'.png'})));
const byId=new Map(EMOJIS.map(e=>[e.id,e])),matches=[...EMOJIS,{...byId.get('heart'),value:'❤'}].sort((a,b)=>b.value.length-a.value.length);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function emojiTokens(text){const result=[];let plain='',i=0;while(i<text.length){const found=matches.find(e=>text.startsWith(e.value,i));if(found){if(plain)result.push({text:plain});plain='';result.push({emoji:found.id});i+=found.value.length;if(text[i]==='\ufe0f')i++;}else{const c=String.fromCodePoint(text.codePointAt(i));plain+=c;i+=c.length;}}if(plain)result.push({text:plain});return result;}
export function richHtml(text){return emojiTokens(text).map(t=>t.text!==undefined?esc(t.text):`<img class="inline-emoji" src="${byId.get(t.emoji).src}" width="200" height="200" alt="${byId.get(t.emoji).label}" title="${byId.get(t.emoji).label}" draggable="false">`).join('');}
const images=new Map();
export function drawEmoji(c,id,x=0,y=0,size=24){const emoji=byId.get(id);if(!emoji||typeof Image==='undefined')return;let img=images.get(id);if(!img){img=new Image();images.set(id,img);img.onload=()=>paintEmojiCanvases();img.src=emoji.src;}c.imageSmoothingEnabled=false;if(img.complete&&img.naturalWidth)c.drawImage(img,x,y,size,size);}
export function paintEmojiCanvases(root=document){root.querySelectorAll('canvas[data-emoji]').forEach(canvas=>{const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);drawEmoji(c,canvas.dataset.emoji,0,0,canvas.width);});}
export function initEmojiPicker(){const picker=document.querySelector('#emoji-picker'),toggle=document.querySelector('#emoji-toggle'),input=document.querySelector('#community-text');document.querySelector('#emoji-grid').innerHTML=EMOJIS.map(e=>`<button type="button" data-pick-emoji="${e.id}" aria-label="${e.label}" title="${e.label}"><img src="${e.src}" width="200" height="200" alt="" draggable="false"></button>`).join('');paintEmojiCanvases();
 const close=()=>{picker.classList.add('hidden');toggle.setAttribute('aria-expanded','false');};toggle.onclick=()=>{const open=picker.classList.toggle('hidden')===false;toggle.setAttribute('aria-expanded',String(open));if(open)picker.querySelector('[data-pick-emoji]').focus();};document.querySelector('#emoji-close').onclick=close;picker.addEventListener('keydown',event=>{const buttons=[...picker.querySelectorAll('[data-pick-emoji]')],index=buttons.indexOf(document.activeElement),step={ArrowRight:1,ArrowLeft:-1,ArrowDown:5,ArrowUp:-5}[event.key];if(index>=0&&step){event.preventDefault();buttons[(index+step+buttons.length)%buttons.length].focus();}});picker.addEventListener('click',event=>{const button=event.target.closest('[data-pick-emoji]');if(!button||input.disabled)return;const value=byId.get(button.dataset.pickEmoji).value,a=input.selectionStart??input.value.length,b=input.selectionEnd??a;if(input.value.length-(b-a)+value.length>input.maxLength)return;input.setRangeText(value,a,b,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus({preventScroll:true});close();});document.addEventListener('click',event=>{if(!picker.contains(event.target)&&!toggle.contains(event.target))close();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!picker.classList.contains('hidden')){close();toggle.focus();}});return close;
}
export function bubbleRows(c,text,maxWidth=205){const chars=emojiTokens(text).flatMap(t=>t.emoji?[{emoji:t.emoji,width:24}]:[...t.text].map(ch=>({text:ch,width:c.measureText(ch).width})));const rows=[{tokens:[],width:0}];for(const token of chars){let row=rows.at(-1);if(row.width+token.width>maxWidth){if(rows.length===3){row.tokens.push({text:'…',width:10});row.width+=10;break;}rows.push({tokens:[],width:0});row=rows.at(-1);}row.tokens.push(token);row.width+=token.width;}return rows;}
export function paintBubbleRow(c,row,x,y){for(const t of row.tokens){if(t.emoji)drawEmoji(c,t.emoji,x,y-20,24);else c.fillText(t.text,x,y);x+=t.width;}}
